6	/**
7	 * Canonical form of a street address: trim and collapse internal whitespace, upper-case,
8	 * and expand common abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE) as whole words.
9	 * Returns {@code ""} for a null or all-whitespace input, so a blank address is rejected
10	 * by the required-field check. Idempotent, so it can be reapplied wherever addresses are
11	 * compared.
12	 */
13	public final class NormaliseAddress {
14	
15	    private static final Map<String, String> ABBREVIATIONS =
16	            Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
17	
18	    private NormaliseAddress() {
19	    }
20	
21	    public static String normalise(String value) {
22	        if (value == null) {
23	            return "";
24	        }
25	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
26	        if (collapsed.isEmpty()) {
27	            return "";
28	        }
29	        StringBuilder sb = new StringBuilder(collapsed.length());
30	        for (String token : collapsed.split(" ")) {
31	            if (sb.length() > 0) {
32	                sb.append(' ');
33	            }
34	            sb.append(ABBREVIATIONS.getOrDefault(token, token));
35	        }
36	        return sb.toString();
37	    }
38	}
